    "Lees aanwijzing {0} nog eens.": "Rileggi la dichiarazione {0}.",
    "Iedereen staat goed. Wie was alleen met het slachtoffer?": "Sono tutti al posto giusto. Chi era solo con la vittima?",
    "{0} kan maar op één plek staan.": "{0.short} può stare in un solo posto.",
