    "tips": {
      "same-row": "Attenzione alla dichiarazione su una riga: una riga va da sinistra a destra e attraversa le pareti.",
      "same-col": "Una colonna va dall’alto in basso per tutta la piantina. Le pareti non contano.",
      "left-of": "«Più a sinistra» vale per tutta la piantina: una colonna più a sinistra, in qualunque stanza.",
      "above": "«Più in alto sulla piantina» vuol dire più vicino al bordo superiore, in qualunque stanza.",
      "not-adjacent": "«Non accanto» esclude solo le quattro caselle confinanti: a sinistra, a destra, sopra e sotto. In diagonale non conta come accanto.",
      "adjacent": "«Proprio accanto» è la casella a sinistra, a destra, sopra o sotto. Mai in diagonale.",
      "alone": "Chi era da solo in una stanza esclude tutti gli altri da quella stanza. Utile per eliminare stanze.",
      "empty-room": "Una stanza vuota secondo il rapporto: è inutile provare a metterci qualcuno.",
      "pos": "Un angolo tocca due pareti, «contro una parete» ne tocca una e «al centro» nessuna.",
      "room-pos": "Guarda quali caselle d’angolo o lungo le pareti di quella stanza sono ancora libere. Spesso gli oggetti ne occupano qualcuna.",
      "room-with": "Una stanza «con una pianta» può avere anche altri oggetti. Trova prima la pianta.",
      "next-to": "Tocca la dichiarazione: l’oggetto si illumina. Valgono solo le caselle che lo toccano di lato.",
      "room-next": "Stanza e oggetto insieme: di solito resta una sola casella.",
      "diff-room": "Non nella stessa stanza: fissa prima la persona di cui sai di più.",
      "same-room": "Stessa stanza: trova la stanza di una delle due persone e saprai anche quella dell’altra.",
      "not-room": "Un «non ero in…» esclude una stanza. Combinalo con la regola sulla vittima.",
      "room": "La dichiarazione più chiara: posiziona per prima questa persona.",
      "fallback": "Comincia dalla dichiarazione che lascia meno possibilità."
    },
    "intros": {
      "kamers": [
        "Stanze",
        "Un sospettato ti dice in quale stanza era. Trova quella stanza sulla piantina e mettilo in una casella qualsiasi al suo interno. Qualcuno dice dove NON era? Allora può stare ovunque, tranne in quella stanza."
      ],
      "hoeken": [
        "Angoli e pareti",
        "Ogni stanza ha tre tipi di casella. In un angolo: la casella tocca due pareti della stanza (in rosso nel disegno). Contro una parete: la casella tocca una sola parete (in oro). Al centro: la casella non tocca nessuna parete (in verde)."
      ],
      "meubels": [
        "Oggetti",
        "Proprio accanto a un oggetto vuol dire: nella casella alla sua sinistra, alla sua destra, sopra o sotto. In diagonale non conta. Non sai che cos’è qualcosa? Toccalo per vederne il nome."
      ],
      "samen": [
        "Insieme o da soli",
        "Nella stessa stanza: metti le due persone in quell’unica stanza. Non nella stessa stanza: mettile in due stanze diverse. «Ero da solo» o «ero da sola»: nessun altro può stare in quella stanza."
      ],
      "naast": [
        "Uno accanto all’altro",
        "Proprio accanto a qualcuno vuol dire: le due caselle si toccano su un lato, a sinistra, a destra, sopra o sotto. In diagonale non conta. Una parete in mezzo va bene, purché le caselle siano affiancate."
      ],
      "rijen": [
        "Righe e colonne",
        "Una riga va da sinistra a destra per tutta la piantina. Una colonna va dall’alto in basso. «Sulla stessa riga» può voler dire anche in un’altra stanza: le pareti non contano."
      ],
      "links": [
        "Più a sinistra, più in alto",
        "Più a sinistra di qualcuno vuol dire: in una colonna più a sinistra, anche se è in un’altra stanza. Più in alto di qualcuno vuol dire: in una riga più vicina al bordo superiore della piantina."
      ],
      "leeg": [
        "Stanze vuote",
        "Secondo il rapporto in quella stanza non c’era nessuno. Quindi non metterci nessuno: puoi saltare del tutto quella stanza."
      ]
    },
    "reactWrong": [
      "Io? Mai!",
      "Non dirai sul serio.",
      "Non ero nemmeno lì!",
      "Chiedi agli altri.",
      "Riguarda la piantina."
    ],
